import {articles,topics,pdfs,topicName,formatDate} from './content.js';
import {diagram,icon} from './diagrams.js';
const main = document.querySelector('#main');
const meta = article => `<div class="article-meta"><span>${topicName(article.topic)}</span><span>${article.readTime} min read</span></div>`;
const card = article => `<a class="article-card" href="#/article/${article.slug}"><div class="card-art">${diagram(article.kind)}</div>${meta(article)}<h3>${article.title}</h3><p>${article.description}</p><div class="card-bottom"><time datetime="${article.date}">${formatDate(article.date)}</time>${icon('upRight')}</div></a>`;
function home() {
 const featured=articles[0];
 main.innerHTML=`<section class="hero page-width"><div class="hero-copy"><div class="eyebrow"><span class="tiny-line"></span>A PERSONAL MATHEMATICS JOURNAL</div><h1>A little curiosity.<br>An <em>infinite</em> plane.</h1><p>Notes on geometry, the elegance of a proof,<br class="desktop-break"> and the pleasure of figuring things out.</p><a class="button primary" href="#/topics">Explore the journal ${icon('arrow')}</a><a class="quiet-link" href="#/about">A little about me ${icon('upRight')}</a></div><div class="hero-figure"><span class="figure-index">FIG. 01 / THE EULER LINE</span>${diagram('euler','Triangle ABC with circumcentre O, centroid G, and orthocentre H')}<div class="figure-caption"><span>Different centres. A shared line.</span><span class="math-caption">OG : GH = 1 : 2</span></div></div></section><div class="journal-strip"><div class="page-width"><span>GEOMETRY IS A WAY OF SEEING.</span><div><span>Explore</span> <a href="#/topics?topic=euclidean">Euclidean geometry ↗</a><a href="#/topics?topic=analytic">Analytic geometry ↗</a><a href="#/topics?topic=combinatorics">Combinatorics ↗</a></div></div></div><section class="page-width featured-section"><div class="section-heading"><h2><span class="section-number">01</span> In the spotlight</h2><span class="eyebrow">A GOOD PLACE TO BEGIN</span></div><a class="featured-story" href="#/article/${featured.slug}"><div class="featured-art"><span class="eyebrow">A STUDY IN TRIANGLE CENTRES</span>${diagram('euler')}<span class="art-footnote">The beauty is in the connection.</span></div><div class="featured-copy"><span class="label">FEATURED ESSAY</span>${meta(featured)}<h2>${featured.title}</h2><p>${featured.description}</p><div class="featured-bottom"><span>Read the story ${icon('arrow')}</span><span>${formatDate(featured.date)}</span></div></div></a></section><section class="page-width latest-section"><div class="section-heading"><h2><span class="section-number">02</span> From the notebook</h2><a href="#/topics" class="text-link">All articles ${icon('arrow')}</a></div><div class="article-grid">${articles.slice(1,4).map(card).join('')}</div></section><section class="page-width archive-invitation"><div class="archive-invitation-icon">${icon('book')}</div><div><span class="eyebrow">FOR YOUR NEXT QUIET AFTERNOON</span><h2>Good mathematics. To go.</h2><p>Collected notes and worked proofs, ready to read, print, and scribble on.</p></div><a class="button outline" href="#/archive">Visit the PDF archive ${icon('arrow')}</a></section>`;
}
document.querySelector('.search-trigger').innerHTML=icon('search');
document.querySelector('.menu-toggle').innerHTML=icon('menu');
function updateThemeButton(){document.querySelector('.theme-toggle').innerHTML=icon(document.documentElement.dataset.theme==='dark'?'sun':'moon');document.querySelector('.theme-toggle').setAttribute('aria-label',`Switch to ${document.documentElement.dataset.theme==='dark'?'light':'dark'} theme`);}
updateThemeButton();
document.querySelector('.theme-toggle').addEventListener('click',()=>{const value=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=value;try{localStorage.setItem('geometry-theme',value)}catch{}updateThemeButton();document.querySelector('meta[name="theme-color"]').content=value==='dark'?'#050505':'#ffffff';});
document.querySelector('.menu-toggle').addEventListener('click',()=>{const nav=document.querySelector('#mobile-nav');nav.hidden=!nav.hidden;document.querySelector('.menu-toggle').setAttribute('aria-expanded',String(!nav.hidden));});
const escapeHTML = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let routeVersion=0;
let archiveView='grid';
let pdfManifest={};
fetch('./pdf/manifest.json').then(r=>r.ok?r.json():{}).then(data=>{pdfManifest=data;document.querySelectorAll('[data-file-size]').forEach(el=>{const bytes=data[el.dataset.fileSize]?.bytes;if(bytes)el.textContent=formatBytes(bytes);});}).catch(()=>{});
const formatBytes = bytes => bytes>=1048576?`${(bytes/1048576).toFixed(1)} MB`:`${Math.ceil(bytes/1024)} KB`;
const urlState = () => {const [path,query='']=(location.hash.slice(1)||'/').split('?');return {path,params:new URLSearchParams(query)};};
const shortTopic = id => ({euclidean:'Euclidean',analytic:'Analytic',combinatorics:'Combinatorics',advanced:'Advanced math'}[id]);
function setMeta(title,description){document.title=title==='Home'?'tomsuhapbia’s Geometry — A mathematics journal':`${title} — tomsuhapbia’s Geometry`;document.querySelector('meta[name="description"]').content=description;document.querySelector('meta[property="og:title"]').content=document.title;document.querySelector('meta[property="og:description"]').content=description;}
function filterControls(items,params,isArchive){const topic=params.get('topic')||'all';return `<div class="filter-bar"><div class="filter-tabs" aria-label="Filter by topic"><button class="filter-tab" data-topic="all" aria-pressed="${topic==='all'}">All ${isArchive?'notes':'articles'} <small>${items.length}</small></button>${topics.map(t=>`<button class="filter-tab" data-topic="${t.id}" aria-pressed="${topic===t.id}">${shortTopic(t.id)} <small>${items.filter(a=>a.topic===t.id).length}</small></button>`).join('')}</div><label class="input-wrap">${icon('search')}<input id="listing-search" type="search" aria-label="Search ${isArchive?'PDF notes':'articles'}" placeholder="Search ${isArchive?'the archive':'articles'}…" value="${escapeHTML(params.get('q')||'')}"></label></div>`;}
function topicsPage(params){setMeta('Geometry topics','Explore essays in Euclidean geometry, analytic geometry, combinatorics, and advanced mathematics.');main.innerHTML=`<div class="page-width listing"><header class="page-heading"><div class="eyebrow">THE NOTEBOOK</div><h1>Follow your curiosity.</h1><p>A collection of ideas worth spending time with. Pick a topic, find a question, and see where the proof takes you.</p></header>${filterControls(articles,params,false)}<div id="topic-description"></div><div class="results-heading"><span id="result-count" role="status"></span><label>Sort by <select id="sort-order" aria-label="Sort articles"><option value="newest">Newest first</option><option value="oldest">Oldest first</option><option value="title">Title, A–Z</option></select></label></div><div id="listing-results" class="article-grid"></div></div>`;bindListing(articles,params,false);}
function pdfCard(pdf){return `<article class="pdf-card"><div class="pdf-card-top"><div class="pdf-card-icon">${icon('file')}</div><span class="eyebrow">${topicName(pdf.topic)}</span></div><h2>${pdf.title}</h2><p>${pdf.description}</p><div class="tags">${pdf.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div><div class="pdf-details"><time datetime="${pdf.date}">${formatDate(pdf.date)}</time><span>${pdf.pages} pages</span><span data-file-size="${pdf.id}">${pdfManifest[pdf.id]?.bytes?formatBytes(pdfManifest[pdf.id].bytes):'PDF'}</span></div><div class="pdf-actions"><button class="button primary" data-pdf="${pdf.id}">${icon('book')} Preview</button><button class="icon-button" data-pdf="${pdf.id}" data-fullscreen aria-label="Preview ${pdf.title} in fullscreen" title="Fullscreen">${icon('expand')}</button><a class="button outline" href="./pdf/${pdf.id}.pdf" download>${icon('download')} Download</a></div></article>`;}
function archivePage(params){setMeta('PDF archive','Download and read complete geometry notes, proofs, worked examples, and exercises.');main.innerHTML=`<div class="page-width listing"><header class="page-heading"><div class="eyebrow">THE READING ROOM</div><h1>A shelf of good ideas.</h1><p>Collected notes, careful proofs, and problems to work through at your own pace. Yours to read, download, and return to.</p></header>${filterControls(pdfs,params,true)}<div class="results-heading"><span id="result-count" role="status"></span><div class="view-switch" aria-label="Archive display"><button class="icon-button" data-view="grid" aria-label="Grid view" aria-pressed="${archiveView==='grid'}">${icon('grid')}</button><button class="icon-button" data-view="list" aria-label="List view" aria-pressed="${archiveView==='list'}">${icon('list')}</button></div></div><div id="listing-results" class="pdf-grid ${archiveView==='list'?'list-view':''}"></div><p class="archive-note">A note on these notes: this opening collection covers classical results, with worked examples and exercises. Each PDF stands on its own; no account is needed to download a copy.</p></div>`;bindListing(pdfs,params,true);}
function bindListing(items,params,isArchive){
 let topic=topics.some(t=>t.id===params.get('topic'))?params.get('topic'):'all';
 let query=params.get('q')||'';
 let order=params.get('sort')||'newest';
 const input=document.querySelector('#listing-search');const sort=document.querySelector('#sort-order');if(sort)sort.value=['newest','oldest','title'].includes(order)?order:'newest';
 function update(){const tokens=query.toLowerCase().trim().split(/\s+/).filter(Boolean);let filtered=items.filter(item=>(topic==='all'||item.topic===topic)&&tokens.every(token=>`${item.title} ${item.subtitle||''} ${item.description} ${topicName(item.topic)} ${item.tags.join(' ')}`.toLowerCase().includes(token)));filtered.sort((a,b)=>order==='title'?a.title.localeCompare(b.title):order==='oldest'?a.date.localeCompare(b.date):b.date.localeCompare(a.date));document.querySelector('#result-count').textContent=`${filtered.length} ${isArchive?'document':'article'}${filtered.length===1?'':'s'}${topic!=='all'?' in '+topicName(topic).toLowerCase():''}`;const results=document.querySelector('#listing-results');results.innerHTML=filtered.length?filtered.map(isArchive?pdfCard:card).join(''):`<div class="empty-state" style="grid-column:1/-1"><h3>No notes on that page.</h3><p>Try a broader search or choose a different topic.</p><button class="button outline" id="clear-filters">Clear filters ${icon('arrow')}</button></div>`;document.querySelectorAll('[data-topic]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.topic===topic)));const description=document.querySelector('#topic-description');if(description){const selected=topics.find(t=>t.id===topic);description.innerHTML=selected?`<div class="topic-intro"><h2>${selected.name}</h2><p>${selected.description}</p></div>`:'';}const nextParams=new URLSearchParams();if(topic!=='all')nextParams.set('topic',topic);if(query)nextParams.set('q',query);if(order!=='newest'&&!isArchive)nextParams.set('sort',order);const nextHash=`#/${isArchive?'archive':'topics'}${nextParams.size?'?'+nextParams:''}`;history.replaceState(null,'',nextHash);document.querySelector('#clear-filters')?.addEventListener('click',()=>{topic='all';query='';input.value='';update();input.focus();});}
 document.querySelectorAll('[data-topic]').forEach(button=>button.addEventListener('click',()=>{topic=button.dataset.topic;update();}));input.addEventListener('input',()=>{query=input.value;update();});sort?.addEventListener('change',()=>{order=sort.value;update();});document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>{archiveView=button.dataset.view;document.querySelector('#listing-results').classList.toggle('list-view',archiveView==='list');document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===archiveView)));}));update();
}
function markdown(source){
 if(!window.marked||!window.DOMPurify)throw Error('The reading libraries did not load.');
 const equations=[];const protectedSource=source.replace(/\$\$([\s\S]+?)\$\$|\$([^\n$]+?)\$/g,(_,display,inline)=>{const index=equations.length;equations.push({tex:display??inline,display:display!==undefined});return `GEOMETRYMATH${index}TOKEN`;});
 let html=DOMPurify.sanitize(marked.parse(protectedSource));
 html=html.replace(/GEOMETRYMATH(\d+)TOKEN/g,(_,n)=>{const eq=equations[Number(n)];return window.katex?katex.renderToString(eq.tex,{displayMode:eq.display,throwOnError:false,trust:false,strict:'warn',output:'htmlAndMathml'}):escapeHTML(eq.tex);});return html;
}
async function articlePage(slug,version){const article=articles.find(a=>a.slug===slug);if(!article)return notFound();setMeta(article.title,article.description);main.innerHTML=`<div class="article-header"><a class="back-link" href="#/topics">${icon('arrow')} Back to the notebook</a>${meta(article)}<h1>${article.title}</h1><p>${article.subtitle}</p><div class="article-byline"><span class="author-dot">t.</span><span>tomsuhapbia</span><span>·</span><time datetime="${article.date}">${formatDate(article.date)}</time></div></div><div class="article-layout"><div><figure class="article-illustration">${diagram(article.kind)}<figcaption>${article.slug==='the-euler-line'?'The circumcentre, centroid, and orthocentre of a triangle.':'A geometric study from the notebook.'}</figcaption></figure><article class="prose" id="article-body" aria-label="Article content"><p role="status">Opening the notebook…</p></article><div class="article-end"><div class="tags">${article.tags.map(t=>`<a class="tag" href="#/topics?q=${encodeURIComponent(t)}">${t}</a>`).join('')}</div></div></div><aside class="article-sidebar" aria-label="Article navigation"><div class="sidebar-inner"><h2 class="toc-title">ON THIS PAGE</h2><nav class="toc" id="article-toc" aria-label="Table of contents"></nav>${article.pdf?`<div class="sidebar-pdf">${icon('file')}<h3>Take the proof with you.</h3><p>Related notes, examples, and exercises in one short PDF.</p><button data-pdf="${article.pdf}">Open the notes ↗</button></div>`:''}</div></aside></div><section class="related-articles page-width"><div class="section-heading"><h2>Keep a little curiosity.</h2><a class="text-link" href="#/topics">All articles ${icon('arrow')}</a></div><div class="article-grid">${articles.filter(a=>a.slug!==slug).slice(0,3).map(card).join('')}</div></section>`;
 try{const response=await fetch(`./posts/${article.slug}.md`);if(!response.ok)throw Error('Article unavailable');const source=await response.text();if(version!==routeVersion)return;document.querySelector('#article-body').innerHTML=markdown(source);const headings=[...document.querySelectorAll('#article-body h2')];headings.forEach((h,i)=>h.id=`section-${i+1}`);document.querySelector('#article-toc').innerHTML=headings.map(h=>`<a href="#/article/${slug}?section=${h.id}" data-section="${h.id}">${h.textContent}</a>`).join('');window.Prism?.highlightAllUnder(document.querySelector('#article-body'));const section=urlState().params.get('section');if(section)document.getElementById(section)?.scrollIntoView();}
 catch{if(version===routeVersion)document.querySelector('#article-body').innerHTML=`<div class="empty-state"><h2>This page couldn’t be loaded.</h2><p>Check your connection and try opening the article again.</p><button class="button outline" id="retry-article">Try again</button></div>`;document.querySelector('#retry-article')?.addEventListener('click',()=>articlePage(slug,routeVersion));}}
function aboutPage(){setMeta('About the journal','A personal notebook of geometry, mathematical proofs, and ideas for curious learners.');main.innerHTML=`<div class="page-width"><header class="page-heading"><div class="eyebrow">BEHIND THE NOTEBOOK</div><h1>Hello, I’m tomsuhapbia.</h1><p>This is a place for the mathematics that makes me pause, reach for a pencil, and look a little closer.</p></header><div class="about-layout"><div class="about-art">${diagram('euler')}<p>There is always another way to see it.</p></div><div class="about-copy"><h2>A notebook, with the pages open.</h2><p>Geometry has a wonderful way of turning a small question into an unexpected connection. A line through a triangle. A circle in the right place. A proof that suddenly feels inevitable.</p><p>This journal brings together mathematical essays, olympiad-style ideas, and academic notes. The aim is simple: to make the reasoning as clear as the result, and to leave enough room for you to try things yourself.</p><h3>THINGS YOU’LL FIND HERE</h3><div class="interest-list"><span>Euclidean geometry</span><span>Analytic geometry</span><span>Combinatorics</span><span>Proofs & inequalities</span></div><h3>A NOTE ON THE CONTENT</h3><p>The opening collection revisits classical mathematics with original explanations, worked examples, and practice questions. Diagrams support the argument; stated assumptions and equations carry the proof.</p><div class="contact-box"><h3>KEEP EXPLORING</h3><p>Start with <a href="#/article/the-euler-line">the Euler line</a>, browse <a href="#/topics">the notebook</a>, or take a set of <a href="#/archive">PDF notes</a> for later.</p></div></div></div></div>`;}
function notFound(){setMeta('Page not found','Return to the mathematics journal.');main.innerHTML=`<section class="not-found"><span class="eyebrow">404 · OUTSIDE THE PLANE</span><h1>A point we haven’t plotted.</h1><p>That page isn’t in this notebook. There are plenty of other ideas to explore.</p><a href="#/" class="button primary">Back to the journal ${icon('arrow')}</a></section>`;}
function route(){const version=++routeVersion;const {path,params}=urlState();document.querySelector('#mobile-nav').hidden=true;document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');document.querySelectorAll('dialog[open]').forEach(d=>d.close());const nav=path==='/topics'||path.startsWith('/article/')?'topics':path==='/archive'?'archive':path==='/about'?'about':'home';document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===nav)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});window.scrollTo(0,0);if(path==='/'){setMeta('Home','A personal collection of geometry, mathematical proofs, and academic notes.');home();}else if(path==='/topics')topicsPage(params);else if(path==='/archive')archivePage(params);else if(path==='/about')aboutPage();else if(path.startsWith('/article/'))articlePage(path.slice('/article/'.length),version);else notFound();if(version>1)main.focus({preventScroll:true});}
window.addEventListener('hashchange',route);
document.querySelector('.skip-link').addEventListener('click',event=>{event.preventDefault();main.focus();main.scrollIntoView();});
document.addEventListener('click',event=>{const section=event.target.closest('[data-section]');if(section){event.preventDefault();document.getElementById(section.dataset.section)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}const pdf=event.target.closest('[data-pdf]');if(pdf){event.preventDefault();document.querySelector('#search-dialog').close();openPdf(pdf.dataset.pdf,pdf.hasAttribute('data-fullscreen'));}const close=event.target.closest('[data-close]');if(close)document.getElementById(close.dataset.close).close();});
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close();});
const searchDialog=document.querySelector('#search-dialog');const searchInput=document.querySelector('#global-search');const searchResults=document.querySelector('#search-results');let searchIndex=-1;
document.querySelector('#search-icon').innerHTML=icon('search');
function renderSearch(){const query=searchInput.value.toLowerCase().trim();const tokens=query.split(/\s+/).filter(Boolean);const all=[...articles.map(a=>({...a,type:'Article'})),...pdfs.map(p=>({...p,type:'PDF note'}))];const results=query?all.filter(item=>tokens.every(token=>`${item.title} ${item.subtitle||''} ${item.description} ${item.tags.join(' ')} ${topicName(item.topic)}`.toLowerCase().includes(token))):all.slice(0,4);searchIndex=-1;searchResults.innerHTML=`<div class="search-label" role="status">${query?`${results.length} RESULT${results.length===1?'':'S'}`:'A FEW IDEAS TO START WITH'}</div>`+(results.length?results.map(item=>`<a class="search-result" href="${item.type==='Article'?'#/article/'+item.slug:'./pdf/'+item.id+'.pdf'}" ${item.type==='PDF note'?`data-pdf="${item.id}"`:''}>${icon(item.type==='Article'?'book':'file')}<div><strong>${item.title}</strong><small>${item.type} · ${topicName(item.topic)}</small></div>${icon('upRight')}</a>`).join(''):`<div class="empty-state"><h3>No results, yet.</h3><p>Try “triangle”, “circles”, or “proof”.</p></div>`);}
function openSearch(){if(document.querySelector('#pdf-dialog').open)document.querySelector('#pdf-dialog').close();searchInput.value='';renderSearch();if(!searchDialog.open)searchDialog.showModal();searchInput.focus();}
document.querySelector('.search-trigger').addEventListener('click',openSearch);searchInput.addEventListener('input',renderSearch);
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(searchDialog.open)searchDialog.close();else openSearch();}});
searchDialog.addEventListener('keydown',e=>{const results=[...searchResults.querySelectorAll('.search-result')];if(['ArrowDown','ArrowUp'].includes(e.key)&&results.length){e.preventDefault();searchIndex=searchIndex===-1?(e.key==='ArrowDown'?0:results.length-1):(searchIndex+(e.key==='ArrowDown'?1:-1)+results.length)%results.length;results.forEach((r,i)=>r.classList.toggle('selected',i===searchIndex));results[searchIndex].focus();}if(e.key==='Enter'&&document.activeElement===searchInput&&results.length){e.preventDefault();results[0].click();}});
searchResults.addEventListener('click',e=>{if(e.target.closest('a'))searchDialog.close();});
const pdfDialog=document.querySelector('#pdf-dialog');const pdfCanvas=document.querySelector('#pdf-canvas');const pdfStage=document.querySelector('#pdf-stage');const pdfStatus=document.querySelector('.pdf-status');let pdfDoc=null,pdfLoading=null,pdfRender=null,pdfPage=1,pdfZoom=1,pdfVersion=0,renderVersion=0,pdfExpanded=false,pdfNativeFullscreen=false;
async function togglePdfFullscreen(expand=!pdfExpanded){pdfExpanded=expand;pdfDialog.classList.toggle('expanded',expand);document.querySelector('#pdf-fullscreen').setAttribute('aria-label',expand?'Exit fullscreen':'Enter fullscreen');try{if(expand&&document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else if(!expand&&document.fullscreenElement)await document.exitFullscreen();}catch{/* The full-window reader remains available when browser fullscreen is restricted. */}renderPdf();}
for(const [selector,name] of [['#pdf-prev','prev'],['#pdf-next','next'],['#pdf-zoom-out','minus'],['#pdf-zoom-in','plus'],['#pdf-fullscreen','expand'],['#pdf-download','download'],['[data-close="pdf-dialog"]','close']])document.querySelector(selector).innerHTML=icon(name);
function updatePdfControls(){document.querySelector('#pdf-pages').textContent=pdfDoc?`${pdfPage} / ${pdfDoc.numPages}`:'— / —';document.querySelector('#pdf-zoom').textContent=`${Math.round(pdfZoom*100)}%`;document.querySelector('#pdf-prev').disabled=!pdfDoc||pdfPage<=1;document.querySelector('#pdf-next').disabled=!pdfDoc||pdfPage>=pdfDoc.numPages;document.querySelector('#pdf-zoom-out').disabled=!pdfDoc||pdfZoom<=.5;document.querySelector('#pdf-zoom-in').disabled=!pdfDoc||pdfZoom>=2;}
async function renderPdf(){if(!pdfDoc)return;const version=++renderVersion;const doc=pdfDoc;const pageNumber=pdfPage;updatePdfControls();try{if(pdfRender){pdfRender.cancel();try{await pdfRender.promise}catch{}}const page=await doc.getPage(pageNumber);if(version!==renderVersion||!pdfDialog.open)return;const base=page.getViewport({scale:1});const fit=Math.min(1.25,Math.max(200,pdfStage.clientWidth-50)/base.width);const viewport=page.getViewport({scale:fit*pdfZoom});const dpr=Math.min(window.devicePixelRatio||1,2);pdfCanvas.width=Math.round(viewport.width*dpr);pdfCanvas.height=Math.round(viewport.height*dpr);pdfCanvas.style.width=viewport.width+'px';pdfCanvas.style.height=viewport.height+'px';pdfCanvas.setAttribute('aria-label',`Page ${pageNumber} of ${doc.numPages}. Use Open original PDF for accessible document text.`);pdfCanvas.hidden=false;pdfStatus.hidden=true;pdfRender=page.render({canvasContext:pdfCanvas.getContext('2d'),viewport,transform:dpr!==1?[dpr,0,0,dpr,0,0]:undefined});await pdfRender.promise;}catch(error){if(error.name!=='RenderingCancelledException'&&version===renderVersion&&pdfDialog.open){pdfStatus.hidden=false;pdfStatus.textContent='This page couldn’t be rendered. You can still open or download the original PDF below.';pdfCanvas.hidden=true;}}}
async function openPdf(id,fullscreen=false){const pdf=pdfs.find(p=>p.id===id);if(!pdf)return;const version=++pdfVersion;renderVersion++;pdfRender?.cancel();if(pdfLoading)pdfLoading.destroy().catch(()=>{});if(pdfDoc)pdfDoc.destroy().catch(()=>{});pdfDoc=null;pdfPage=1;pdfZoom=1;document.querySelector('#pdf-title').textContent=pdf.title;document.querySelector('#pdf-download').href=`./pdf/${pdf.id}.pdf`;document.querySelector('#pdf-native').href=`./pdf/${pdf.id}.pdf`;pdfCanvas.hidden=true;pdfStatus.hidden=false;pdfStatus.textContent='Opening your notes…';updatePdfControls();if(!pdfDialog.open)pdfDialog.showModal();if(fullscreen)togglePdfFullscreen(true);try{const pdfjs=await import('./vendor/pdf.mjs');if(version!==pdfVersion)return;pdfjs.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.mjs',import.meta.url).href;pdfLoading=pdfjs.getDocument({url:new URL(`./pdf/${pdf.id}.pdf`,import.meta.url).href,cMapUrl:new URL('./vendor/cmaps/',import.meta.url).href,cMapPacked:true,standardFontDataUrl:new URL('./vendor/standard_fonts/',import.meta.url).href,wasmUrl:new URL('./vendor/wasm/',import.meta.url).href});const doc=await pdfLoading.promise;if(version!==pdfVersion){await doc.destroy();return;}pdfDoc=doc;await renderPdf();}catch{if(version!==pdfVersion)return;pdfStatus.hidden=false;pdfStatus.textContent='The preview isn’t available in this browser. Open the original PDF below, or download a copy to keep reading.';}}
pdfDialog.addEventListener('close',()=>{pdfVersion++;renderVersion++;pdfRender?.cancel();if(pdfLoading){pdfLoading.destroy().catch(()=>{});pdfLoading=null;}pdfDoc=null;pdfExpanded=false;pdfDialog.classList.remove('expanded');document.querySelector('#pdf-fullscreen').setAttribute('aria-label','Enter fullscreen');if(pdfNativeFullscreen&&document.fullscreenElement)document.exitFullscreen().catch(()=>{});pdfNativeFullscreen=false;});
document.querySelector('#pdf-prev').addEventListener('click',()=>{if(pdfDoc&&pdfPage>1){pdfPage--;renderPdf();pdfStage.scrollTo(0,0);}});document.querySelector('#pdf-next').addEventListener('click',()=>{if(pdfDoc&&pdfPage<pdfDoc.numPages){pdfPage++;renderPdf();pdfStage.scrollTo(0,0);}});document.querySelector('#pdf-zoom-out').addEventListener('click',()=>{pdfZoom=Math.max(.5,Math.round((pdfZoom-.25)*100)/100);renderPdf();});document.querySelector('#pdf-zoom-in').addEventListener('click',()=>{pdfZoom=Math.min(2,Math.round((pdfZoom+.25)*100)/100);renderPdf();});document.querySelector('#pdf-fullscreen').addEventListener('click',()=>togglePdfFullscreen());document.addEventListener('fullscreenchange',()=>{if(document.fullscreenElement){pdfNativeFullscreen=true;}else if(pdfNativeFullscreen){pdfNativeFullscreen=false;pdfExpanded=false;pdfDialog.classList.remove('expanded');document.querySelector('#pdf-fullscreen').setAttribute('aria-label','Enter fullscreen');}renderPdf();});
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(pdfDialog.open)renderPdf();},150);});
function addContact(){if(urlState().path!=='/about')return;const box=document.querySelector('.contact-box');if(box)box.innerHTML=`<h3>LET’S TALK MATHEMATICS</h3><p>Have a question, a different proof, or a correction? I’d be glad to hear from you.</p><div class="contact-links"><a href="mailto:tomsuhapbia@gmail.com">tomsuhapbia@gmail.com ${icon('upRight')}</a><a href="https://artofproblemsolving.com/community/user/tomsuhapbia" target="_blank" rel="noopener noreferrer">Find me on Art of Problem Solving ${icon('upRight')}</a></div>`;}
window.addEventListener('hashchange',addContact);
route();
addContact();
